  "name"                                   VARCHAR(16777216),
  "repository_url"                         VARCHAR(16777216),
  "revision"                               VARCHAR(16777216),
  "size"                                   NUMBER(38,0),
  "workbook_id"                            NUMBER(38,0),
  CONSTRAINT "pk_hist_workbooks" PRIMARY KEY ("id"),
  CONSTRAINT "fk_hist_workbooks_workbook_id" FOREIGN KEY ("workbook_id") REFERENCES "workbooks" ("id")
);

CREATE OR REPLACE TABLE "projects_contents" (
  "content_id"                             NUMBER(38,0),
  "content_type"                           VARCHAR(16777216),
  "id"                                     NUMBER(38,0),
  "project_id"                             NUMBER(38,0),
  "site_id"                                NUMBER(38,0),
  CONSTRAINT "pk_projects_contents" PRIMARY KEY ("id"),
  CONSTRAINT "fk_projects_contents_project_id" FOREIGN KEY ("project_id") REFERENCES "projects" ("id")
);

CREATE OR REPLACE TABLE "system_users" (
  "activated_at"                           TIMESTAMP_NTZ,
  "activation_code"                        VARCHAR(16777216),
  "admin_level"                            NUMBER(38,0),
  "asset_key_id"                           NUMBER(38,0),
  "auth_user_id"                           VARCHAR(16777216),
  "created_at"                             TIMESTAMP_NTZ,
  "custom_display_name"                    BOOLEAN,
  "deleted_at"                             TIMESTAMP_NTZ,
  "domain_id"                              NUMBER(38,0),
  "email"                                  VARCHAR(16777216),
  "failed_login_attempts"                  NUMBER(38,0),
  "force_password_update"                  BOOLEAN,
  "friendly_name"                          VARCHAR(16777216),
  "hashed_password"                        VARCHAR(16777216),
  "id"                                     NUMBER(38,0),
  "keychain"                               VARCHAR(16777216),
  "last_failed_login"                      TIMESTAMP_NTZ,
  "last_password_update"                   TIMESTAMP_NTZ,
  "lock_version"                           NUMBER(38,0),
  "name"                                   VARCHAR(16777216),
  "protected_password"                     VARCHAR(16777216),
  "protected_password_bad_format"          BOOLEAN,
  "salt"                                   VARCHAR(16777216),
  "state"                                  VARCHAR(16777216),
  "sys"                                    BOOLEAN,
  "updated_at"                             TIMESTAMP_NTZ,
  CONSTRAINT "pk_system_users" PRIMARY KEY ("id"),
  CONSTRAINT "fk_system_users_domain_id" FOREIGN KEY ("domain_id") REFERENCES "domains" ("id")
);

CREATE OR REPLACE TABLE "_users" (
  "domain_id"                              NUMBER(38,0),
  "domain_name"                            VARCHAR(16777216),
  "domain_short_name"                      VARCHAR(16777216),
  "friendly_name"                          VARCHAR(16777216),
  "id"                                     NUMBER(38,0),
  "licensing_role_id"                      NUMBER(38,0),
  "licensing_role_name"                    VARCHAR(16777216),
  "login_at"                               TIMESTAMP_NTZ,
  "name"                                   VARCHAR(16777216),
  "site_id"                                NUMBER(38,0),
  "system_user_id"                         NUMBER(38,0),
  CONSTRAINT "pk__users" PRIMARY KEY ("id"),
  CONSTRAINT "fk__users_system_user_id" FOREIGN KEY ("system_user_id") REFERENCES "system_users" ("id")
);

CREATE OR REPLACE TABLE "historical_events" (
  "created_at"                             TIMESTAMP_NTZ,
  "details"                                VARCHAR(16777216),
  "duration_in_ms"                         NUMBER(38,0),
  "hist_actor_site_id"                     NUMBER(38,0),
  "hist_actor_user_id"                     NUMBER(38,0),
  "hist_capability_id"                     NUMBER(38,0),
  "hist_collection_id"                     NUMBER(38,0),
  "hist_column_id"                         NUMBER(38,0),
  "hist_comment_id"                        NUMBER(38,0),
  "hist_config_id"                         NUMBER(38,0),
  "hist_data_connection_id"                NUMBER(38,0),
  "hist_data_quality_indicator_id"         NUMBER(38,0),
  "hist_data_role_id"                      NUMBER(38,0),
  "hist_database_id"                       NUMBER(38,0),
  "hist_datasource_id"                     NUMBER(38,0),
  "hist_flow_draft_id"                     NUMBER(38,0),
  "hist_flow_id"                           NUMBER(38,0),
  "hist_group_id"                          NUMBER(38,0),
  "hist_licensing_role_id"                 NUMBER(38,0),
  "hist_metric_id"                         NUMBER(38,0),
  "hist_project_id"                        NUMBER(38,0),
  "hist_published_connection_id"           NUMBER(38,0),
  "hist_remote_agent_id"                   NUMBER(38,0),
  "hist_schedule_id"                       NUMBER(38,0),
  "hist_table_id"                          NUMBER(38,0),
  "hist_tag_id"                            NUMBER(38,0),
  "hist_target_site_id"                    NUMBER(38,0),
  "hist_target_user_id"                    NUMBER(38,0),
  "hist_task_id"                           NUMBER(38,0),
  "hist_view_id"                           NUMBER(38,0),
  "hist_workbook_id"                       NUMBER(38,0),
  "historical_event_type_id"               NUMBER(38,0),
  "id"                                     NUMBER(38,0),
  "is_failure"                             BOOLEAN,
  "worker"                                 VARCHAR(16777216),
  CONSTRAINT "pk_historical_events" PRIMARY KEY ("id"),
  CONSTRAINT "fk_historical_events_hist_actor_user_id" FOREIGN KEY ("hist_actor_user_id") REFERENCES "hist_users" ("id"),
  CONSTRAINT "fk_historical_events_hist_collection_id" FOREIGN KEY ("hist_collection_id") REFERENCES "hist_collections" ("id"),
  CONSTRAINT "fk_historical_events_hist_datasource_id" FOREIGN KEY ("hist_datasource_id") REFERENCES "hist_datasources" ("id"),
  CONSTRAINT "fk_historical_events_hist_flow_id" FOREIGN KEY ("hist_flow_id") REFERENCES "hist_flows" ("id"),
  CONSTRAINT "fk_historical_events_hist_metric_id" FOREIGN KEY ("hist_metric_id") REFERENCES "hist_metrics" ("id"),
  CONSTRAINT "fk_historical_events_hist_project_id" FOREIGN KEY ("hist_project_id") REFERENCES "hist_projects" ("id"),
  CONSTRAINT "fk_historical_events_hist_schedule_id" FOREIGN KEY ("hist_schedule_id") REFERENCES "hist_schedules" ("id"),
  CONSTRAINT "fk_historical_events_hist_target_site_id" FOREIGN KEY ("hist_target_site_id") REFERENCES "hist_sites" ("id"),
  CONSTRAINT "fk_historical_events_hist_task_id" FOREIGN KEY ("hist_task_id") REFERENCES "hist_tasks" ("id"),
  CONSTRAINT "fk_historical_events_hist_view_id" FOREIGN KEY ("hist_view_id") REFERENCES "hist_views" ("id"),
  CONSTRAINT "fk_historical_events_hist_workbook_id" FOREIGN KEY ("hist_workbook_id") REFERENCES "hist_workbooks" ("id"),
  CONSTRAINT "fk_historical_events_historical_event_type_id" FOREIGN KEY ("historical_event_type_id") REFERENCES "historical_event_types" ("type_id")
);

CREATE OR REPLACE TABLE "users" (
  "created_at"                             TIMESTAMP_NTZ,
  "extracts_required"                      BOOLEAN,
  "id"                                     NUMBER(38,0),
  "lock_version"                           NUMBER(38,0),
  "login_at"                               TIMESTAMP_NTZ,
  "luid"                                   VARCHAR(16777216),
  "nonce"                                  VARCHAR(16777216),
  "raw_data_suppressor_tristate"           NUMBER(38,0),
  "row_limit"                              NUMBER(38,0),
  "site_id"                                NUMBER(38,0),
  "site_role_id"                           NUMBER(38,0),
  "storage_limit"                          NUMBER(38,0),
  "system_admin_auto"                      BOOLEAN,
  "system_user_id"                         NUMBER(38,0),
  "updated_at"                             TIMESTAMP_NTZ,
  CONSTRAINT "pk_users" PRIMARY KEY ("id"),
  CONSTRAINT "fk_users_site_id" FOREIGN KEY ("site_id") REFERENCES "sites" ("id"),
  CONSTRAINT "fk_users_site_role_id" FOREIGN KEY ("site_role_id") REFERENCES "site_roles" ("id"),
  CONSTRAINT "fk_users_system_user_id" FOREIGN KEY ("system_user_id") REFERENCES "system_users" ("id")
);
